  nd = rs + rz + rz -> 4096 * (q - 1) < nd <= 4096 * q -> msz = 4096 * q + 4096 -> 2 <= lin -> 2 ^ 20 <= ov ->
  73728 <= msz <= 2 ^ 31 + 16384 /\ msz mod 4096 = 0 /\ 8 * (msz / 8) = msz /\ msz + msz / 8 + 8192 + 131072 + 2 ^ 19 <= lin * n + ov /\ 4096 < n /\ 4096 + rz + n <= msz /\ 32 <= rz <= 2048.
